import test from 'node:test';
import assert from 'node:assert/strict';
import { createInvoice, lineTotal, lineDiscount, lineVat, invoiceTotals, addLine, removeLine, issueInvoice, applyVoucher } from '../src/invoices.js';
import { TIER_DISCOUNTS } from '../src/customers.js';
import { daysBetween } from '../src/dates.js';

test('createInvoice builds an invoice with enriched lines', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  assert.equal(r.ok, true);
  assert.equal(r.value.customerId, 'C-001');
  assert.equal(r.value.issueDate, '2026-10-07');
  assert.equal(r.value.status, 'draft');
  assert.equal(r.value.lines.length, 1);
  assert.equal(r.value.lines[0].sku, 'DES-HOUR');
  assert.equal(r.value.lines[0].name, 'Design work (hour)');
  assert.equal(r.value.lines[0].qty, 5);
  assert.equal(r.value.lines[0].unitPrice, 8500);
  assert.equal(r.value.lines[0].vatRate, 21);
});

test('createInvoice normalizes customer ID', () => {
  const r = createInvoice({
    customerId: '  c-001  ',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  assert.equal(r.ok, true);
  assert.equal(r.value.customerId, 'C-001');
});

test('createInvoice accepts lowercase customer ID', () => {
  const r = createInvoice({
    customerId: 'c-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  assert.equal(r.ok, true);
  assert.equal(r.value.customerId, 'C-003');
});

test('createInvoice accepts mixed case with spaces', () => {
  const r = createInvoice({
    customerId: ' C-002 ',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  assert.equal(r.ok, true);
  assert.equal(r.value.customerId, 'C-002');
});

test('createInvoice handles multiple lines', () => {
  const r = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 10 },
      { sku: 'LOGO-PACK', qty: 1 },
    ],
  });
  assert.equal(r.ok, true);
  assert.equal(r.value.lines.length, 2);
  assert.equal(r.value.lines[0].name, 'Design work (hour)');
  assert.equal(r.value.lines[1].name, 'Logo package');
});

test('createInvoice reports unknown customer', () => {
  const r = createInvoice({
    customerId: 'C-999',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  assert.deepEqual(r, { ok: false, error: 'CUSTOMER_NOT_FOUND' });
});

