test('lineVat with VAT-exempt product', () => {
  const line = { qty: 5, unitPrice: 8500, discountPercent: 0, vatRate: 0 };
  const vat = lineVat(line);
  assert.equal(vat, 0);
});

test('lineVat with 9% VAT', () => {
  const line = { qty: 5, unitPrice: 1000, discountPercent: 0, vatRate: 9 };
  // Line total: 5000
  // VAT: 5000 * 0.09 = 450
  const vat = lineVat(line);
  assert.equal(vat, 450);
});

test('lineVat with decimal discount', () => {
  const line = { qty: 5, unitPrice: 1000, discountPercent: 12.5, vatRate: 21 };
  // Line total: 5000
  // Discount: 5000 * 0.125 = 625
  // Amount after discount: 4375
  // VAT: 4375 * 0.21 = 918.75, rounded to 919
  const vat = lineVat(line);
  assert.equal(vat, 919);
});

test('lineVat clamps to 0 when amount becomes negative', () => {
  const line = { qty: 100, unitPrice: 100, discountPercent: 100, vatRate: 21 };
  // Line total: 10000
  // Discount: 10000
  // Amount after discount: 0
  // VAT: 0
  const vat = lineVat(line);
  assert.equal(vat, 0);
});

test('invoiceTotals returns vat in response', () => {
  const invoice = {
    lines: [{ qty: 5, unitPrice: 1000, discountPercent: 0, vatRate: 21 }],
  };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.vat, 1050);
});

test('invoiceTotals calculates total as subtotal - discount + vat', () => {
  const invoice = {
    lines: [{ qty: 5, unitPrice: 1000, discountPercent: 10, vatRate: 21 }],
  };
  const totals = invoiceTotals(invoice);
  const expectedSubtotal = 5000;
  const expectedDiscount = 500;
  const expectedAmountAfterDiscount = 4500;
  const expectedVat = Math.round(expectedAmountAfterDiscount * 0.21);
  const expectedTotal = expectedSubtotal - expectedDiscount + expectedVat;
  assert.equal(totals.subtotal, expectedSubtotal);
  assert.equal(totals.discount, expectedDiscount);
  assert.equal(totals.vat, expectedVat);
  assert.equal(totals.total, expectedTotal);
});

test('invoiceTotals with multiple lines and mixed VAT rates', () => {
  const invoice = {
    lines: [
      { qty: 5, unitPrice: 1000, discountPercent: 0, vatRate: 21 },
