    ],
  };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 15000);
  assert.equal(totals.discount, 0);
  assert.equal(totals.vat, 1050 + 450 + 0);
  assert.equal(totals.total, 16500);
});

test('invoiceTotals VAT rounded per line', () => {
