test('invoiceTotals with voucher larger than discount + VAT', () => {
  const r = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  assert.equal(r.ok, true);
  const r2 = applyVoucher(r.value, { code: 'BIGDEAL', amount: 100000 });
  assert.equal(r2.ok, true);
  const totals = invoiceTotals(r2.value);
  // Subtotal: 5 * 8500 = 42500
  // Discount (0%): 0
  // VAT (21%): 42500 * 0.21 = 8925
  // Total should be clamped to 0: 42500 - 0 + 8925 - 100000 = -48575 -> 0
  assert.equal(totals.total, 0);
});

