    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 10 }],
  });
  assert.equal(r.ok, true);
  const r2 = applyVoucher(r.value, { code: 'SUMMER20', amount: 5000 });
  assert.equal(r2.ok, true);
  const totals = invoiceTotals(r2.value);
  assert.equal(totals.voucher, 5000);
  // Subtotal: 10 * 8500 = 85000
  // Discount (5%): 4250
  // VAT (21%): (85000 - 4250) * 0.21 = 16957.5 ~= 16958
  // Total: 85000 - 4250 + 16958 - 5000 = 92708
  assert.equal(totals.subtotal, 85000);
  assert.equal(totals.discount, 4250);
  assert.equal(totals.vat, 16958);
  assert.equal(totals.total, 92708);
});

